create or replace function public.set_account_workspace() returns trigger language plpgsql security invoker set search_path=public as $$ begin if new.workspace_id is null then select workspace_id into new.workspace_id from public.workspace_members where user_id=(select auth.uid()) order by created_at limit 1; end if; if new.mode='MASTER' and new.group_name='Default group' then new.group_name:=new.label; end if; return new; end; $$;
create or replace function public.sync_account_group() returns trigger language plpgsql security definer set search_path=public as $$ declare g uuid; begin insert into public.copy_groups(workspace_id,name,master_account_id) values(new.workspace_id,new.group_name,case when new.mode='MASTER' then new.id else null end) on conflict(workspace_id,name) do update set master_account_id=coalesce(public.copy_groups.master_account_id,excluded.master_account_id) returning id into g; insert into public.copy_group_accounts(group_id,account_id,role,copy_enabled) values(g,new.id,new.mode::text,new.copy_status='ACTIVE') on conflict(group_id,account_id) do update set role=excluded.role,copy_enabled=excluded.copy_enabled; return new; end; $$;
drop trigger if exists trading_accounts_group_sync on public.trading_accounts;
create trigger trading_accounts_group_sync after insert or update of group_name,mode,copy_status on public.trading_accounts for each row execute function public.sync_account_group();
